import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Paper/Implementation Alignment","description":"","frontmatter":{"title":"Paper/Implementation Alignment","type":"adr","date":"2026-09-18T00:00:00.000Z","status":"accepted","status_note":"Accepted — five ordered phases align the implementation with the paper."},"headers":[],"relativePath":"handl/project/adrs/0120-paper-implementation-alignment.md","filePath":"vendored/handl/project/adrs/0120-paper-implementation-alignment.md"}`),a={name:`handl/project/adrs/0120-paper-implementation-alignment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0120-paper-implementation-alignment" tabindex="-1">ADR-0120: Paper/Implementation Alignment <a class="header-anchor" href="#adr-0120-paper-implementation-alignment" aria-label="Permalink to “ADR-0120: Paper/Implementation Alignment”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Phase 1 — arrows as values</strong>: a <code>function</code> used as a value lowers to <code>Arr { value: Term }</code> (quoted, no environment capture); <code>call(f, x)</code> lowers to <code>seq(pair(quote f, x), app)</code>, while flow <code>x &gt;&gt;&gt; f</code> stays <code>seq(x, f)</code>.</li><li><strong>Phase 1 — no self-application</strong>: <code>desugar.data</code>&#39;s recursor becomes <code>loop(step)</code> feedback, and there is no currying — parameters are products (partial application, if ever needed, is a prefix-splice of products).</li><li><strong>Phase 2 — composition axes</strong>: <code>Term::Seq</code> gains an <code>axis</code> slot (default 0); <code>&gt;&gt;&gt;[k]</code> is grammar/YAML only, and types track globular source/target with <code>tgt_k(a) = src_k(b)</code>.</li><li><strong>Phase 3 — <code>dim</code> unification</strong>: <code>ArrSource::Foreign(grade)</code> merges into the morphism dimension; <code>~[n]~&gt;</code> means dimension.</li><li><strong>Phase 3 — effects as cells</strong>: <code>op</code> is a cell and <code>handle</code> is a cell interpreter (an <code>(N+1)</code>-cell mapping an effectful <code>N</code>-cell to a pure one).</li><li><strong>Phase 4 — dependent structure</strong>: <code>Family&lt;A&gt;</code>, <code>Π</code>, <code>Σ</code> enter via <code>types.yaml</code> + desugar; reindexing <code>f*</code> is composition, and the adjunctions are laws, not engine primitives.</li><li><strong>Phase 5 — laws as <code>M[2]</code> terms</strong>: <code>f ~[2]~&gt; g</code> parses to a <code>Term</code> and feeds <code>law_inference</code>; <code>Path</code>/<code>Equiv</code>/<code>Refine</code>/<code>witness</code>/<code>cell_*</code> are derived arrows, not primitives.</li><li><strong>Ordering is load-bearing</strong>: <code>1 → 2 → 3 → (4, 5 in parallel)</code>, with the decision gates of the design doc at each step.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The implementation diverged from the paper in five places — captured environments, self-application, axis-free composition, grade/dimension confusion, and laws as a separate fragment — so the same program had two readings. The phases restore one reading in dependency order.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep quoted functions capturing environments</strong> — they are resolved at lower time.</li><li><strong>Keep self-application as the recursor</strong> — <code>loop</code> feedback replaces it.</li><li><strong>Keep laws in a separate fragment</strong> — they are <code>M[2]</code> terms.</li><li><strong>Re-order the phases</strong> — later phases depend on earlier ones.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The paper and implementation agree at every phase boundary.</li><li>Each phase has a gate; 4 and 5 can run in parallel.</li><li>Derived arrows replace special-case ops.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — <code>Term</code> (<code>axis</code>, <code>Arr</code> quote), <code>desugar</code>.</li><li><code>crates/handl-kit-data-canonical/data/</code> — <code>types.yaml</code>, grammar.</li><li>Phase gates in the design doc and parity tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The five phases, their numbered changes and the decision gates: +<a href="./../design/0120-paper-implementation-alignment.html"><code>design/0120-paper-implementation-alignment.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};